// Options → custom properties, shared by the custom elements and the Svelte and React components.
export const STYLE_PROPS = {
  minHeight: "min-height",
  height: "height",
  blend: "mix-blend-mode",
};
const STYLE_KEYS = Object.keys(STYLE_PROPS);

export const LAYER_KEYS = [
  "colStart", "colEnd", "alignX", "alignY",
  "translateX", "translateY", "rotate", "scale", "bleed", "fadeDuration",
  "fluid", "fluidFrom", "fluidTo",
  ...STYLE_KEYS,
];

export const SECTION_KEYS = [
  "fadeDistance", "fadeDuration", "triggerInset", "stackBelow", "fullWidthBelow",
  ...STYLE_KEYS,
];

export const GROUP_KEYS = ["stackBelow", "fullWidthBelow", "fluid", "fluidFrom", "fluidTo", ...STYLE_KEYS];

export const ROW_KEYS = ["rowGap", "stackBelow", "fullWidthBelow", "fluid", "fluidFrom", "fluidTo", ...STYLE_KEYS];

export const ANIM_KEYS = [
  "xStart", "xMid", "xEnd", "yStart", "yMid", "yEnd",
  "scaleStart", "scaleMid", "scaleEnd", "rotateStart", "rotateMid", "rotateEnd",
  "skewStart", "skewMid", "skewEnd",
  "filterStart", "filterMid", "filterEnd", "opacityStart", "opacityMid", "opacityEnd",
  "parallax", "sectionParallax", "pinDistance",
  "range", "ease", "timeline", "composition",
  "inRange", "outRange", "inEase", "outEase",
  "transformRange", "transformEase", "transformTimeline", "transformComposition",
  "filterRange", "filterEase", "filterTimeline", "filterComposition",
  "opacityRange", "opacityEase", "opacityTimeline",
  "parallaxRange", "parallaxTimeline", "parallaxComposition",
  "extra", "extraRange", "extraTimeline", "extraComposition",
  "blend",
];

// The animation options a layer takes too (it animates itself): all but blend, which it has already.
export const LAYER_ANIM_KEYS = ANIM_KEYS.filter((key) => key !== "blend");

export function toVarName(key) {
  return "--pt-" + key.replace(/[A-Z]/g, (c) => "-" + c.toLowerCase());
}

export function toCssName(key) {
  return STYLE_PROPS[key] ?? toVarName(key);
}

export function attrToKey(attr) {
  return attr.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
}

export const WIDTH_PRESETS = { xs: 375, sm: 640, md: 768, lg: 1024, xl: 1280, "2xl": 1536 };

// Your own named widths, from defineWidths() or <html data-pt-widths="phone:700">.
const customWidths = {};
let htmlWidths = { source: null, map: {} };

export function defineWidths(widths) {
  for (const [name, px] of Object.entries(widths)) customWidths[name] = parseFloat(px);
}

function namedWidth(name) {
  if (name in customWidths) return customWidths[name];
  if (typeof document !== "undefined") {
    const source = document.documentElement?.dataset.ptWidths ?? "";
    if (source !== htmlWidths.source) {
      htmlWidths = { source, map: {} };
      for (const part of source.trim().split(/\s+/).filter(Boolean)) {
        const at = part.indexOf(":");
        htmlWidths.map[part.slice(0, at)] = parseFloat(part.slice(at + 1));
      }
    }
    if (name in htmlWidths.map) return htmlWidths.map[name];
  }
  return WIDTH_PRESETS[name];
}

// Splits on spaces outside brackets, so "700:max(75lvh, 38rem)" stays whole.
function splitTopLevel(text) {
  const parts = [];
  let depth = 0;
  let part = "";
  for (const c of text.trim()) {
    if (c === "(") depth++;
    if (c === ")") depth--;
    if (/\s/.test(c) && depth === 0) {
      if (part) parts.push(part);
      part = "";
    } else {
      part += c;
    }
  }
  if (part) parts.push(part);
  return parts;
}

export const RESPONSIVE_KEYS = new Set([
  "colStart", "colEnd", "alignX", "alignY", "translateX", "translateY", "rotate", "scale",
  "bleed", "minHeight", "height", "rowGap",
  "xStart", "xMid", "xEnd", "yStart", "yMid", "yEnd",
  "scaleStart", "scaleMid", "scaleEnd", "rotateStart", "rotateMid", "rotateEnd",
  "skewStart", "skewMid", "skewEnd", "opacityStart", "opacityMid", "opacityEnd",
  "parallax", "sectionParallax",
]);

export function parseWidthMap(value) {
  let entries;
  if (value && typeof value === "object" && !Array.isArray(value)) {
    entries = Object.entries(value);
  } else if (typeof value === "string" && value.includes(":")) {
    entries = splitTopLevel(value).map((part) => {
      const at = part.indexOf(":");
      return [part.slice(0, at), part.slice(at + 1)];
    });
  } else {
    return null;
  }
  const stops = [];
  for (const [width, v] of entries) {
    const px = /^\d+(\.\d+)?(px)?$/.test(width) ? parseFloat(width) : namedWidth(width);
    if (!Number.isFinite(px)) {
      throw new Error(`portamento: unknown width "${width}" in a width map (use px, ${Object.keys(WIDTH_PRESETS).join(", ")}, or a name from defineWidths())`);
    }
    stops.push([px, String(v)]);
  }
  return stops.sort((a, b) => a[0] - b[0]);
}

// Each key list as a set, made once per list.
const keySets = new WeakMap();
const keySet = (keys) => {
  let set = keySets.get(keys);
  if (!set) keySets.set(keys, (set = new Set(keys)));
  return set;
};

// First value, plus (next - this) × progress per segment; tan(atan2(a, b)) is a / b as a number.
export function widthMapValue(stops) {
  if (stops.length === 1) return stops[0][1];
  let expr = stops[0][1];
  for (let i = 1; i < stops.length; i++) {
    const [w0, v0] = stops[i - 1];
    const [w1, v1] = stops[i];
    if (w1 === w0) {
      expr += ` + (${v1} - ${v0}) * clamp(0, tan(atan2(var(--_pt-vw, 100vw) - ${w0}px + 1px, 1px)) * 1e5, 1)`;
      continue;
    }
    expr += ` + (${v1} - ${v0}) * clamp(0, tan(atan2(var(--_pt-vw, 100vw) - ${w0}px, ${w1 - w0}px)), 1)`;
  }
  return `calc(${expr})`;
}

// Without tan() (before Chrome 111) the calc() above is invalid; there a width
// map steps instead: each value holds from its width up, and the first one
// below that. Two values at one width switch there, as they do when sliding.
export function widthMapStep(stops, width) {
  let value = stops[0][1];
  for (const [w, v] of stops) if (width >= w) value = v;
  return value;
}

export function toVars(options, keys, { width } = {}) {
  const vars = {};
  const wanted = keySet(keys);
  for (const key in options) {
    if (!wanted.has(key)) continue;
    const value = options[key];
    if (value == null || value === false) continue;
    if (key === "bleed" && (value === true || value === "")) continue; // a class, not a value
    if (key === "triggerInset" && /\S\s+\S/.test(String(value).trim())) {
      // two values: top, then bottom, like margin
      const [top, bottom] = splitTopLevel(String(value));
      vars["--pt-trigger-inset-top"] = top;
      vars["--pt-trigger-inset-bottom"] = bottom;
      continue;
    }
    const map = RESPONSIVE_KEYS.has(key) ? parseWidthMap(value) : null;
    if (map) {
      const px = (v) => (key in STYLE_PROPS && /^-?[\d.]+$/.test(v) ? `${v}px` : v);
      const stops = map.map(([w, v]) => [w, px(v)]);
      vars[toCssName(key)] = width == null ? widthMapValue(stops) : widthMapStep(stops, width);
      if (key === "colStart" || key === "colEnd") vars["--_pt-fluid-cols"] = "1"; // rows keep these on mobile
      continue;
    }
    const bare = typeof value === "number" || /^-?[\d.]+$/.test(value);
    vars[toCssName(key)] = bare && key in STYLE_PROPS && key !== "blend" ? `${value}px` : String(value);
  }
  return vars;
}

export function toReactStyle(options, keys) {
  const style = {};
  for (const [name, value] of Object.entries(toVars(options, keys))) {
    const reactName = name.startsWith("--")
      ? name
      : name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
    style[reactName] = value;
  }
  return style;
}

export function toStyle(options, keys) {
  return Object.entries(toVars(options, keys))
    .map(([name, value]) => `${name}: ${value};`)
    .join(" ");
}

export function pick(props, keys) {
  const wanted = keySet(keys);
  const picked = {};
  const rest = {};
  for (const key in props) (wanted.has(key) ? picked : rest)[key] = props[key];
  return [picked, rest];
}

export function overlapClass(overlap) {
  return overlap ? "pt-layer--overlap" : "";
}
