// Keeps the reader's place when the window width changes. Docs: README.md.
const CANDIDATES = [
  ".pt-layer:not(.pt-layer--pinned)", "pt-layer:not([pinned])",
  ".pt-row", "pt-row", ".pt-group", "pt-group", ".pt-section", "pt-section",
].join(", ");

export function keepPlaceOnResize({ root = document } = {}) {
  if (typeof window === "undefined") return () => {};
  const html = document.documentElement;
  // the browser's own scroll anchoring would fight the correction
  const ownAnchoring = html.style.overflowAnchor;
  html.style.overflowAnchor = "none";

  let place = null;
  let width = window.innerWidth;
  let timer = 0;
  let frame = 0;

  // The smallest candidate crossing the middle of the screen, and how far
  // through it the middle is.
  const remember = () => {
    const middle = window.innerHeight / 2;
    let best = null;
    for (const el of root.querySelectorAll(CANDIDATES)) {
      const r = el.getBoundingClientRect();
      if (r.height > 0 && r.top <= middle && r.bottom >= middle && (!best || r.height < best.height)) {
        best = { el, height: r.height, at: (middle - r.top) / r.height };
      }
    }
    place = best;
  };

  const restore = () => {
    frame = 0;
    if (!place?.el.isConnected) return;
    const r = place.el.getBoundingClientRect();
    const by = r.top + place.at * r.height - window.innerHeight / 2;
    if (Math.abs(by) >= 1) window.scrollBy({ top: by, behavior: "instant" });
  };

  // Only once scrolling settles, so nothing runs per frame while scrolling.
  const onScroll = () => {
    clearTimeout(timer);
    timer = setTimeout(remember, 150);
  };
  // Width changes only: phone toolbars change the height mid-scroll.
  const onResize = () => {
    if (window.innerWidth === width) return;
    width = window.innerWidth;
    clearTimeout(timer); // our own correction shouldn't re-pick the place mid-resize
    if (!frame) frame = requestAnimationFrame(restore);
  };

  remember();
  window.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("resize", onResize);
  return () => {
    window.removeEventListener("scroll", onScroll);
    window.removeEventListener("resize", onResize);
    clearTimeout(timer);
    cancelAnimationFrame(frame);
    html.style.overflowAnchor = ownAnchoring;
  };
}
