// Custom elements: <pt-section>, <pt-group>, <pt-row>, <pt-layer>, <pt-anim>. Docs: README.md.
import {
  ANIM_KEYS, GROUP_KEYS, LAYER_ANIM_KEYS, LAYER_KEYS, ROW_KEYS, SECTION_KEYS,
  toVars,
} from "./props.js";

const LAYER_ALL_KEYS = [...LAYER_KEYS, ...LAYER_ANIM_KEYS];

export { defineWidths } from "./props.js";

const toAttr = (key) => key.replace(/[A-Z]/g, (c) => "-" + c.toLowerCase());

// Each element type's attribute name -> option, worked out once.
const attrMaps = new WeakMap();
const attrMap = (keys) => {
  let map = attrMaps.get(keys);
  if (!map) attrMaps.set(keys, (map = new Map(keys.map((key) => [toAttr(key), key]))));
  return map;
};

// What each element set from attributes, so removing one never clears the author's own styles.
const applied = new WeakMap();

// Before Chrome 111 there's no tan(), so a width map's calc() is invalid; there
// each element with a width map works out its values for the current width,
// and again on resize (old browsers only, so the cost doesn't matter).
const slides = typeof CSS === "undefined" || CSS.supports("width", "calc(1px * tan(atan2(1px, 1px)))");
const stepped = new Map(); // element -> its keys, for elements with width maps
let resizing = 0;
if (!slides) {
  addEventListener("resize", () => {
    cancelAnimationFrame(resizing);
    resizing = requestAnimationFrame(() => {
      for (const [el, keys] of stepped) el.isConnected ? syncVars(el, keys) : stepped.delete(el);
    });
  });
}

// Reads the attributes the element has (not every one it could have), writes
// the custom properties that changed, removes the ones no longer set, and
// returns the options it read.
function syncVars(el, keys) {
  const names = attrMap(keys);
  const options = {};
  for (const { name, value } of el.attributes) {
    const key = names.get(name);
    if (key) options[key] = value;
  }
  const vars = toVars(options, keys, slides ? {} : { width: innerWidth });
  if (!slides) {
    if (Object.values(options).some((value) => value.includes(":"))) stepped.set(el, keys);
    else stepped.delete(el);
  }
  const mine = applied.get(el) ?? new Set();
  applied.set(el, mine);
  for (const name of mine) {
    if (!(name in vars)) {
      el.style.removeProperty(name);
      mine.delete(name);
    }
  }
  for (const name in vars) {
    if (el.style.getPropertyValue(name) !== vars[name]) el.style.setProperty(name, vars[name]);
    mine.add(name);
  }
  return options;
}

const isBlankText = (node) =>
  node.nodeType === Node.TEXT_NODE && !node.textContent.trim();

// A layer's content goes in a .pt-layer__inner wrapper, including content
// added later: one observer watches every layer, and layers that connect while
// the page is still parsing (before their children exist) wrap once it's done.
function wrap(layer) {
  let inner = null;
  for (const child of layer.children) {
    if (child.classList.contains("pt-layer__inner")) {
      inner = child;
      break;
    }
  }
  const strays = Array.from(layer.childNodes).filter(
    (node) => node !== inner && !isBlankText(node),
  );
  if (inner && strays.length === 0) return;
  if (!inner) {
    inner = document.createElement("div");
    inner.className = "pt-layer__inner";
  }
  inner.append(...strays);
  if (inner.parentNode !== layer) layer.append(inner);
}
let layerObserver = null;
const waiting = new Set();

// The elements are hidden until defined; fade them in rather than snap
// (layout.css), for as long as --pt-reveal-duration, then drop the transition.
function reveal() {
  const html = document.documentElement;
  if (customElements.get("pt-layer")) return;
  html.setAttribute("data-pt-revealing", "");
  const value = getComputedStyle(html).getPropertyValue("--pt-reveal-duration").trim();
  const ms = value.endsWith("ms") ? parseFloat(value) : value ? parseFloat(value) * 1000 : 600;
  setTimeout(() => html.removeAttribute("data-pt-revealing"), (Number.isFinite(ms) ? ms : 600) + 100);
}

export function defineElements() {
  if (typeof customElements === "undefined") return;
  reveal();

  // While upgrading, the browser reports every attribute one by one and then
  // connects; reading them all once, on connect, does the same work once.
  class PtElement extends HTMLElement {
    #connected = false;
    connectedCallback() {
      this.#connected = true;
      this.sync();
    }
    attributeChangedCallback() {
      if (this.#connected) this.sync();
    }
    sync() {
      syncVars(this, this.constructor.keys);
    }
  }
  const observing = (keys) => [...attrMap(keys).keys()];

  class PtSection extends PtElement {
    static keys = SECTION_KEYS;
    static observedAttributes = observing(SECTION_KEYS);
  }

  class PtGroup extends PtElement {
    static keys = GROUP_KEYS;
    static observedAttributes = observing(GROUP_KEYS);
  }

  class PtRow extends PtElement {
    static keys = ROW_KEYS;
    static observedAttributes = observing(ROW_KEYS);
  }

  const LAYER_ANIM_SET = new Set(LAYER_ANIM_KEYS);
  class PtLayer extends PtElement {
    static keys = LAYER_ALL_KEYS;
    static observedAttributes = observing(LAYER_ALL_KEYS);
    #animClass = false;

    // Animation attributes animate the layer itself, through .pt-anim
    // (added here, and removed only if it was added here).
    sync() {
      const options = syncVars(this, LAYER_ALL_KEYS);
      const animated = Object.keys(options).some((key) => LAYER_ANIM_SET.has(key));
      if (animated && !this.classList.contains("pt-anim")) {
        this.classList.add("pt-anim");
        this.#animClass = true;
      } else if (!animated && this.#animClass) {
        this.classList.remove("pt-anim");
        this.#animClass = false;
      }
    }

    connectedCallback() {
      super.connectedCallback();
      if (document.readyState === "loading") {
        if (waiting.size === 0) {
          document.addEventListener("DOMContentLoaded", () => {
            for (const layer of waiting) wrap(layer);
            waiting.clear();
          }, { once: true });
        }
        waiting.add(this);
      } else {
        wrap(this);
      }
      layerObserver ??= new MutationObserver((records) => {
        for (const layer of new Set(records.map((record) => record.target))) wrap(layer);
      });
      layerObserver.observe(this, { childList: true });
    }
  }

  class PtAnim extends PtElement {
    static keys = ANIM_KEYS;
    static observedAttributes = observing(ANIM_KEYS);
  }

  for (const [name, ctor] of [
    ["pt-section", PtSection],
    ["pt-group", PtGroup],
    ["pt-row", PtRow],
    ["pt-layer", PtLayer],
    ["pt-anim", PtAnim],
  ]) {
    if (!customElements.get(name)) customElements.define(name, ctor);
  }
}

defineElements();
